using System.ComponentModel;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search functionality using the Brave Search API.
/// Falls back to a simulated search when no API key is configured.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _braveApiKey;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _braveApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
    }

    [Description("Search the web for information on a topic. Returns a list of relevant results with titles, URLs, and descriptions.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrWhiteSpace(_braveApiKey))
        {
            return await SearchWithBraveAsync(query, maxResults);
        }

        return SimulateSearch(query, maxResults);
    }

    private async Task<string> SearchWithBraveAsync(string query, int maxResults)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("X-Subscription-Token", _braveApiKey);
        request.Headers.Add("Accept", "application/json");

        var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var sb = new StringBuilder();
        sb.AppendLine($"Web search results for: \"{query}\"");
        sb.AppendLine();

        if (json.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var results))
        {
            int index = 0;
            foreach (var result in results.EnumerateArray())
            {
                if (index >= maxResults) break;
                index++;
                var title = result.GetProperty("title").GetString();
                var url = result.GetProperty("url").GetString();
                var description = result.TryGetProperty("description", out var desc)
                    ? desc.GetString() : "No description available";

                sb.AppendLine($"[{index}] {title}");
                sb.AppendLine($"    URL: {url}");
                sb.AppendLine($"    {description}");
                sb.AppendLine();
            }
        }

        return sb.Length > 0 ? sb.ToString() : "No results found.";
    }

    private static string SimulateSearch(string query, int maxResults)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Web search results for: \"{query}\"");
        sb.AppendLine("(Simulated results — set BRAVE_API_KEY for live web search)");
        sb.AppendLine();
        sb.AppendLine($"[1] Wikipedia — {query}");
        sb.AppendLine($"    URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}");
        sb.AppendLine($"    Comprehensive encyclopedia article covering the key aspects of {query}.");
        sb.AppendLine();
        sb.AppendLine($"[2] Recent Research on {query}");
        sb.AppendLine($"    URL: https://scholar.example.com/search?q={Uri.EscapeDataString(query)}");
        sb.AppendLine($"    A collection of recent academic papers and research findings related to {query}.");
        sb.AppendLine();
        sb.AppendLine($"[3] {query} — Latest News and Developments");
        sb.AppendLine($"    URL: https://news.example.com/{Uri.EscapeDataString(query)}");
        sb.AppendLine($"    Up-to-date news coverage and analysis on the latest developments in {query}.");
        return sb.ToString();
    }
}

